fn frame(t: i32) {
    let kick = [1, 0, 0, 0, 1, 0, 0, 0];
    let hat = [1, 1, 0, 1, 1, 0, 1, 1];
    let step: i32 = (t / 8) % 8;
    if t % 8 == 0 {
        if kick[step] == 1 { host::audio::tone(55, 120, 0); }
        if hat[step] == 1 { host::audio::noise(25); }
    }
    host::display::clear(0x0a0a0a);
    host::display::draw_string(16, 60, "STEP SEQ", 0xffffff, 3);
    let mut i: i32 = 0;
    while i < 8 {
        let x: i32 = 16 + i * 60;
        let mut kc: i32 = 0x202020;
        if kick[i] == 1 { kc = 0xff4020; }
        host::display::fill_rect(x, 200, 48, 48, kc);
        let mut hc: i32 = 0x202020;
        if hat[i] == 1 { hc = 0x20c0ff; }
        host::display::fill_rect(x, 280, 48, 48, hc);
        i = i + 1;
    }
    host::display::fill_rect(16 + step * 60, 180, 48, 8, 0xffff00);
    host::display::draw_string(16, 350, "RED KICK BLUE HAT", 0x808080, 1);
    host::display::present();
}
